import { worldHTML } from "./views.js";
/** Minimal reusable desktop/mobile adapter. The host controls mounting and styling.
 * Navigation is generated by Gen.E.Wrist, never by a host manifest.
 */
export function mountWorldPanel({ root, wrist, onNotice = () => {} } = {}) {
  if (!root?.addEventListener || !wrist?.snapshot)
    throw Error("DOM root and wrist required");
  let closed = false;
  const render = () => {
    if (closed) return;
    const state = wrist.snapshot();
    root.innerHTML =
      '<nav aria-label="Persistent Gen.E.Wrist navigation"><button data-nav="home">HOME</button><button data-nav="back">BACK</button><button data-nav="universal">UNIVERSAL MODE</button><button data-nav="world">WORLD</button></nav><section aria-label="Gen.E.Wrist screen">' +
      (state.destination === "world"
        ? worldHTML(state, {
            demoId: null,
            allowDemos: false,
            allowContextChange: false,
          })
        : "<h3>" +
          (state.destination === "home"
            ? "Home / local fallback"
            : "Universal Mode") +
          "</h3><p>Your universal identity is available. The full standalone console contains the eighteen bundled applications. This embedded component displays the active host’s World screen.</p>") +
      '</section><p role="status" class="adapter-status"></p>';
  };
  const report = (error) => {
    const status = root.querySelector(".adapter-status");
    if (status) status.textContent = "Action unavailable: " + error.message;
    onNotice(error.message);
  };
  const click = async (event) => {
    const button = event.target.closest("button");
    if (!button || !root.contains(button) || button.disabled) return;
    try {
      if (button.dataset.nav === "home") wrist.home();
      else if (button.dataset.nav === "back") wrist.back();
      else if (button.dataset.nav) wrist.navigate(button.dataset.nav);
      else if (button.dataset.action === "host-action")
        await wrist.requestWorldAction(button.dataset.id);
      else if (button.dataset.action === "host-disconnect")
        wrist.disconnectWorld();
      else if (button.dataset.action === "host-revoke")
        wrist.setWorldGrants([]);
      else if (button.dataset.action === "navigate")
        wrist.navigate(button.dataset.id === "world" ? "world" : "universal");
      else if (button.dataset.action === "app")
        wrist.openApp(button.dataset.id);
      else
        onNotice(
          "This screen is owned by the host integration; use its full presentation for local applications.",
        );
    } catch (error) {
      report(error);
    }
  };
  const change = (event) => {
    if (!event.target.classList.contains("grant-input")) return;
    try {
      wrist.setWorldGrants(
        [...root.querySelectorAll(".grant-input:checked")].map(
          (input) => input.dataset.capability,
        ),
      );
    } catch (error) {
      report(error);
    }
  };
  root.addEventListener("click", click);
  root.addEventListener("change", change);
  const stop = wrist.subscribe(render);
  render();
  return Object.freeze({
    render,
    dispose() {
      if (closed) return;
      closed = true;
      stop();
      root.removeEventListener("click", click);
      root.removeEventListener("change", change);
      wrist.setInputCaptured(false);
      wrist.disconnectWorld();
      root.replaceChildren();
    },
  });
}
